INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Wird Subnetting häufig in LANs eingesetzt?', 2, '[{"text": "Ja", "correct": true, "because": "Organisiert lokale Netze"}, {"text": "Nein", "correct": false, "because": "Praxisüblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse könnte ein LAN wie 192.168.1.0/24 in Subnetze aufteilen?', 3, '[{"text": "192.168.1.0/26", "correct": true, "because": "4 Subnetze mit 64 Adressen"}, {"text": "192.168.1.0/23", "correct": false, "because": "Größerer Bereich"}, {"text": "192.168.1.0/32", "correct": false, "because": "Einzeladresse"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) WANs nutzen oft größere Subnetze. b) LANs bevorzugen kleine Subnetze.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) für Reichweite, b) für Effizienz"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Praxisbeispielen für LAN und WAN?', 4, '[{"text": "Subnetzgröße", "correct": false, "because": "Bestimmt Struktur"}, {"text": "Adressbereiche", "correct": false, "because": "Definiert Netze"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein LAN wie 192.168.1.0/24 typischerweise /30 für kleine Gruppen nutzt?', 2, '[{"text": "Ja", "correct": true, "because": "2 Hosts pro Subnetz"}, {"text": "Nein", "correct": false, "because": "Praxisüblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmaske wäre für ein WAN mit vielen Standorten sinnvoll?', 3, '[{"text": "/22", "correct": true, "because": "1024 Adressen, flexibel"}, {"text": "/30", "correct": false, "because": "Nur 2 Hosts"}, {"text": "/26", "correct": false, "because": "Zu klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netze sind typische Praxisbeispiele?', 5, '[{"text": "LAN mit 192.168.1.0/24", "correct": true, "because": "Lokales Netz"}, {"text": "WAN mit 10.0.0.0/16", "correct": true, "because": "Großes Netz"}, {"text": "LAN mit 8.8.8.0/24", "correct": false, "because": "Öffentlich"}, {"text": "WAN mit 172.16.0.0/30", "correct": false, "because": "Zu klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) LANs nutzen oft private IPs. b) WANs sind immer öffentlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "WANs können privat sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Praxisbeispiele von LAN und WAN?', 4, '[{"text": "IP-Bereiche", "correct": false, "because": "Definiert Netze"}, {"text": "Subnetzmasken", "correct": false, "because": "Strukturiert Aufteilung"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ein LAN mit 192.168.1.0/24 typischerweise 254 Hosts?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-24) - 2 = 254"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich wäre für ein WAN-Subnetz von 10.0.0.0/16 mit /20?', 4, '[{"text": "10.0.0.0-10.0.15.255", "correct": true, "because": "Inkrement 4096"}, {"text": "10.0.0.0-10.0.0.255", "correct": false, "because": "Für /24"}, {"text": "10.0.16.0-10.0.31.255", "correct": false, "because": "2. Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass LANs keine Subnetze brauchen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Subnetze erhöhen Effizienz"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem LAN-Praxisbeispiel?', 3, '[{"text": "Kleine Subnetze", "correct": true, "because": "Reduziert Broadcast"}, {"text": "Schnelligkeit", "correct": false, "because": "Struktur zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Planung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein WAN wie 172.16.0.0/16 hat viele Hosts. b) LANs nutzen oft /30.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) für Punkt-zu-Punkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse hat ein LAN mit 192.168.1.0/24 und /26?', 5, '[{"text": "4 Subnetze", "correct": true, "because": "2^(26-24) = 4"}, {"text": "62 Hosts pro Subnetz", "correct": true, "because": "2^(32-26) - 2 = 62"}, {"text": "2 Subnetze", "correct": false, "because": "Für /25"}, {"text": "256 Hosts insgesamt", "correct": false, "because": "Pro Subnetz kleiner"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei LAN- und WAN-Praxisbeispielen unwichtig?', 3, '[{"text": "Subnetzgröße", "correct": false, "because": "Bestimmt Struktur"}, {"text": "IP-Bereiche", "correct": false, "because": "Definiert Netze"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt ein WAN wie 10.0.0.0/16 oft /24-Subnetze?', 3, '[{"text": "Ja", "correct": true, "because": "Flexibel für Standorte"}, {"text": "Nein", "correct": false, "because": "Praxisüblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein LAN mit 192.168.1.0/28 16 Subnetze hat?', 2, '[{"text": "Ja", "correct": true, "because": "2^(28-24) = 16"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich ist typisch für ein WAN-Subnetz von 172.16.0.0/16 mit /18?', 4, '[{"text": "172.16.0.0-172.16.63.255", "correct": true, "because": "Inkrement 16384"}, {"text": "172.16.0.0-172.16.0.255", "correct": false, "because": "Für /24"}, {"text": "172.16.64.0-172.16.127.255", "correct": false, "because": "2. Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hosts hat ein LAN-Subnetz mit 192.168.1.0/24 und /29?', 3, '[{"text": "6", "correct": true, "because": "2^(32-29) - 2 = 6"}, {"text": "8", "correct": false, "because": "Ohne Abzug"}, {"text": "14", "correct": false, "because": "Für /28"}]');
